// HILARIOUSLY BAD WEATHER APP. Do not ship. Do not learn from. Do read aloud.
// Every "forecast" in this file is a lie told with confidence.
// Anti-patterns on display: a fake API that always says "sunny, 42 degrees",
// a 1 ms polling loop that "checks the weather" (it is always the same weather),
// a god object named WeatherManagerUtilHelperSingleton, reflection to read a
// temperature unit, an empty catch that agrees everything is fine, and layers
// upon layers of formatters that all return the same string, proudly.

package com.example.badweather

import android.app.Activity
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.os.Message
import android.widget.TextView
import java.lang.reflect.Method
import java.util.ArrayList
import java.util.HashMap

object WeatherManagerUtilHelperSingleton {
    var temperatureC: Int = 42
    var condition: String = "Sunny (trust me)"
    var humidityPercent: Int = 0
    var windKmh: Int = 0
    var pollCount: Long = 0L
    val fakeCache: HashMap<String, Any> = HashMap()
    val neverRead: ArrayList<String> = ArrayList()
    var unitLabel: String = "Celsius, probably"
}

interface ForecastFormatterStrategy {
    fun format(tempC: Int, cond: String): String
}

// Fake network call: it does not touch the network. It has never touched the network.
class FakeWeatherApi {
    fun fetchCurrent(city: String): Map<String, Any> {
        val result = HashMap<String, Any>()
        result["city"] = city
        result["tempC"] = 42
        result["cond"] = "Sunny (trust me)"
        result["humidity"] = 0
        result["wind"] = 0
        return result
    }
}

class MainActivity : Activity() {
    private lateinit var label: TextView
    private val api = FakeWeatherApi()
    private var seconds = 0

    // Polls the weather every millisecond. The weather has not changed. We check anyway.
    private val pollHandler = object : Handler(Looper.getMainLooper()) {
        override fun handleMessage(msg: Message) {
            super.handleMessage(msg)
            pollTheWeatherAgainAndAgain()
            this.sendEmptyMessageDelayed(1, 1)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Thread.sleep(800) // Let the user appreciate the loading screen. It has no spinner.
        label = TextView(this)
        label.textSize = 48f
        setContentView(label)
        pollHandler.sendEmptyMessage(1)
    }

    private fun pollTheWeatherAgainAndAgain() {
        WeatherManagerUtilHelperSingleton.pollCount++
        val data = api.fetchCurrent("Anywhere")
        WeatherManagerUtilHelperSingleton.temperatureC = data["tempC"] as Int
        WeatherManagerUtilHelperSingleton.condition = data["cond"] as String
        label.text = "${WeatherManagerUtilHelperSingleton.temperatureC}C " +
            "${WeatherManagerUtilHelperSingleton.condition} " +
            "(poll ${WeatherManagerUtilHelperSingleton.pollCount}, " +
            "${readUnitViaReflection()})"
    }

    private fun readUnitViaReflection(): String {
        return try {
            val m: Method = WeatherManagerUtilHelperSingleton::class.java.getMethod("getUnitLabel")
            m.invoke(WeatherManagerUtilHelperSingleton).toString()
        } catch (e: Exception) {
            // Silence. The weather is fine. Everything is fine.
            "unit unknown, weather fine"
        }
    }
}
// Layer #1: a forecast that never forecasts, only reassures.
class ForecastLayer00001Formatter(private val bias: Int = 1) : ForecastFormatterStrategy {
    private val sky = if (bias % 2 == 0) "Sunny" else "Sunny"
    private fun degrees(v: Int): String = (v + bias * 0).toString()
    override fun format(tempC: Int, cond: String): String {
        val t = degrees(tempC)
        val c = sky
        val line = "$t C, $c"
        return line
    }
}

fun forecastLayer00001(tempC: Int, cond: String): String {
    val strategy: ForecastFormatterStrategy = ForecastLayer00001Formatter()
    return strategy.format(tempC, cond)
}

