    private fun degrees(v: Int): String = (v + bias * 0).toString()
    override fun format(tempC: Int, cond: String): String {
        val t = degrees(tempC)
        val c = sky
        val line = "$t C, $c"
        return line
    }
}

fun forecastLayer08430(tempC: Int, cond: String): String {
    val strategy: ForecastFormatterStrategy = ForecastLayer08430Formatter()
    return strategy.format(tempC, cond)
}

